{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.11.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[{"sourceId":14016803,"sourceType":"datasetVersion","datasetId":8929301}],"dockerImageVersionId":31192,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-12-06T18:01:17.784110Z\",\"iopub.execute_input\":\"2025-12-06T18:01:17.784664Z\",\"iopub.status.idle\":\"2025-12-06T18:02:07.933913Z\",\"shell.execute_reply.started\":\"2025-12-06T18:01:17.784632Z\",\"shell.execute_reply\":\"2025-12-06T18:02:07.932877Z\"}}\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom math import sqrt\nfrom skimage.io import imread, imshow\nfrom skimage.color import rgb2gray, label2rgb\nfrom skimage.feature import blob_dog, blob_log, blob_doh\nfrom skimage.morphology import erosion, dilation, opening, closing\nfrom skimage.measure import label, regionprops\n\n#Pedimos la ruta de la imagen al usuario\nimagen = input('Escribe la ruta de la imagen:')\n# Convertimos la imagen en escala de grises\nimg_rbc = rgb2gray(imread(imagen))\n\n# Binarizamos la imagen para identificar las partículas\nimg_rbc_bw = (img_rbc < 0.26) * 1\n\n\n# Etiquetamos los píxeles conectados y los contamos\nlabel_img_rbc = label(img_rbc_bw)\nrbc_props = regionprops(label_img_rbc)\ncell_count = label_img_rbc.max()\nprint(\"\\nCantidad de partículas detectadas: {}\".format(cell_count))","metadata":{"_uuid":"f6377980-ab02-416a-a7e2-5348aba48324","_cell_guid":"69f13875-eb6d-4fe0-ab37-da494d42f2fa","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}